#include <3ds.h>
#include <stdio.h>
#include <sys/stat.h>
static const char *names[]={"Gray steps","Near black","Near white","Gradient","Vertical stripes","Horizontal stripes","Checkerboard","Red","Green","Blue","White","Black","Mid gray","Color cycle"};
static void draw(int p,unsigned frame){u16 h,w;u8 *fb=gfxGetFramebuffer(GFX_TOP,GFX_LEFT,&h,&w);for(int x=0;x<w;x++)for(int y=0;y<h;y++){int v=0;switch(p){case 0:v=(x*11/w)*255/10;break;case 1:v=x*32/w;break;case 2:v=224+x*32/w;break;case 3:v=x*255/(w-1);break;case 4:v=(x%2)*255;break;case 5:v=(y%2)*255;break;case 6:v=((x+y)%2)*255;break;case 10:v=255;break;case 12:v=128;break;}u8 r=v,g=v,b=v;if(p==7)r=255;if(p==8)g=255;if(p==9)b=255;if(p==13){unsigned n=(frame/120)%3;r=n==0?255:0;g=n==1?255:0;b=n==2?255:0;}size_t i=(x*h+h-1-y)*3;fb[i]=b;fb[i+1]=g;fb[i+2]=r;}}
static Result readval(Handle h,u32 cmd,u32 *v){u32 *b=getThreadCommandBuffer();b[0]=cmd;Result r=svcSendSyncRequest(h);if(R_FAILED(r))return r;r=(Result)b[1];if(R_SUCCEEDED(r))*v=b[2];return r;}
int main(void){gfxInitDefault();gfxSet3D(false);consoleInit(GFX_BOTTOM,NULL);Handle h=0;u32 top=0,bottom=0;Result open=srvGetServiceHandle(&h,"mcu::RTC"),rt=open,rb=open;if(R_SUCCEEDED(open)){rt=readval(h,0x00440000,&top);rb=readval(h,0x00460000,&bottom);svcCloseHandle(h);}int p=0,saved=0;unsigned frame=0;while(aptMainLoop()){hidScanInput();u32 k=hidKeysDown();if(k&KEY_START)break;if(k&KEY_RIGHT)p=(p+1)%14;if(k&KEY_LEFT)p=(p+13)%14;if(k&KEY_A){mkdir("sdmc:/3ds",0777);mkdir("sdmc:/3ds/LCDLab",0777);FILE *f=fopen("sdmc:/3ds/LCDLab/report.txt","w");if(f){fprintf(f,"Service %08lX\nTop result %08lX raw %08lX\nBottom result %08lX raw %08lX\nPattern %s\n",(unsigned long)open,(unsigned long)rt,(unsigned long)top,(unsigned long)rb,(unsigned long)bottom,names[p]);saved=fclose(f)==0?1:-1;}else saved=-1;}draw(p,frame++);printf("\x1b[1;1H\x1b[2JLCD Lab - READ ONLY\n\nPattern: %s\nLeft/Right: pattern\nA: save report\nSTART: exit\n\nService: %08lX\nTop result: %08lX\nTop raw: %08lX\nBottom result: %08lX\nBottom raw: %08lX\nReport: %d\nNo calibration writes.\n",names[p],(unsigned long)open,(unsigned long)rt,(unsigned long)top,(unsigned long)rb,(unsigned long)bottom,saved);gfxFlushBuffers();gfxSwapBuffers();gspWaitForVBlank();}gfxExit();return 0;}
